<template><BioNexusDialog ref="box" size="fullscreen" kicker="Catálogo de exámenes" title="Ajustar precios" :prevent-close="saving || hasChanges" @before-close="requestClose" @close="reset"><section class="workspace"><BioNexusSectionPanel title="Exámenes incluidos" icon="science" description="Selecciona los exámenes que recibirán el ajuste." variant="accent"><BioNexusDataGrid :row-data="workingRows" :column-defs="includedColumns" :components="components" :get-row-id="getId" :row-selection="selection" :search-enabled="true" v-model:search-model-value="includedSearch" search-placeholder="Buscar examen incluido" :export-options="false" :page-size="10" :min-grid-height="300" :max-grid-height="430" @grid-ready="includedReady"><template #actions><BioNexusActionButton variant="secondary" icon="add" label="Agregar exámenes" @click="scopeDialog?.open()">Agregar exámenes</BioNexusActionButton><BioNexusActionButton variant="secondary" icon="remove_done" :disabled="includedSelected.length===0" @click="removeSelected">Quitar seleccionados</BioNexusActionButton><BioNexusActionButton variant="secondary" icon="delete_sweep" :disabled="workingRecords.length===0" @click="clearAll">Limpiar lista</BioNexusActionButton></template></BioNexusDataGrid></BioNexusSectionPanel><BioNexusSectionPanel title="Operación y tarifas" icon="price_change" description="Define el tipo de ajuste, el porcentaje y las tarifas afectadas." variant="accent"><div class="adjustment-top"><div class="controls"><BioNexusFormField label="Operación" field-id="adjust-operation"><BioNexusSearchableSelect id="adjust-operation" v-model="operation" :options="operationOptions" @change="clearError" /></BioNexusFormField><BioNexusFormField label="Porcentaje" field-id="adjust-percentage" :error="showErrors ? percentageError : ''"><BioNexusNumericInput id="adjust-percentage" v-model="percentageValue" :decimals="2" :min="0" :max="percentageMaximum" :invalid="showErrors && Boolean(percentageError)" @input="clearError" /></BioNexusFormField></div><section class="tariffs"><header><strong>Tarifas</strong><BioNexusActionButton variant="secondary" :icon="allSelected ? 'deselect' : 'select_all'" @click="toggleAll">{{ allSelected ? 'Quitar todas' : 'Seleccionar todas' }}</BioNexusActionButton></header><div><BioNexusCheckbox v-for="tariff in activeTariffs" :key="tariff.id" :model-value="tariffIds.includes(Number(tariff.id))" :label="tariff.name" @update:model-value="value=>toggleTariff(tariff.id,value)" /></div></section></div><section class="summary"><strong>{{ operationLabel }} {{ percentageDisplay }}%</strong><span>{{ workingRecords.length }} examen(es) · {{ groupCount }} grupo(s) · {{ tariffIds.length }} tarifa(s) · {{ previewRows.length }} cambio(s)</span></section></BioNexusSectionPanel><BioNexusSectionPanel title="Vista previa" icon="visibility" description="Revisa los cambios calculados antes de aplicar el ajuste." variant="accent"><section class="preview-launch"><span class="preview-count">{{ previewRows.length }} cambio(s) calculado(s)</span><BioNexusActionButton class="preview-action" variant="primary" icon="visibility" :disabled="previewRows.length===0" @click="previewDialog?.open(previewRows,operation)">Abrir vista previa</BioNexusActionButton></section></BioNexusSectionPanel><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{ errorMessage }}</div><ExamPriceAdjustmentScopeDialog ref="scopeDialog" :groups="groups" :excluded-ids="workingRecords.map(x=>x.id)" @add="addRecords" /><ExamPriceAdjustmentPreviewDialog ref="previewDialog" /><BioNexusConfirmDialog ref="discardDialog" /></section><template #footer><BioNexusActionButton variant="secondary" icon="cancel" :disabled="saving" @click="requestClose">Cancelar</BioNexusActionButton><BioNexusActionButton variant="primary" icon="price_change" :loading="saving" :disabled="submitDisabled" @click="submit">Aplicar ajuste</BioNexusActionButton></template></BioNexusDialog></template>
<script setup>import{computed,ref}from"vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusCheckbox from"@/components/ui/BioNexusCheckbox.vue";import BioNexusDataGrid from"@/components/grid/BioNexusDataGrid.vue";import BioNexusGridActionsCell from"@/components/grid/BioNexusGridActionsCell.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import BioNexusConfirmDialog from"@/components/ui/BioNexusConfirmDialog.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusSectionPanel from"@/components/ui/BioNexusSectionPanel.vue";import BioNexusNumericInput from"@/components/ui/BioNexusNumericInput.vue";import BioNexusSearchableSelect from"@/components/ui/BioNexusSearchableSelect.vue";import ExamPriceAdjustmentScopeDialog from"@/components/examcatalog/ExamPriceAdjustmentScopeDialog.vue";import ExamPriceAdjustmentPreviewDialog from"@/components/examcatalog/ExamPriceAdjustmentPreviewDialog.vue";import{formatRegionalNumber,formatUsdPrice}from"@/services/regionalFormatter";import{useRegionalSettingsStore}from"@/stores/regionalSettings";const props=defineProps({saving:Boolean,group:{type:Object,default:null},groups:{type:Array,default:()=>[]},records:{type:Array,default:()=>[]},selectedRecords:{type:Array,default:()=>[]},tariffs:{type:Array,default:()=>[]}}),emit=defineEmits(["confirm"]),settings=useRegionalSettingsStore(),box=ref(null),scopeDialog=ref(null),previewDialog=ref(null),discardDialog=ref(null),original=ref(""),showErrors=ref(false),operation=ref("increase"),percentageValue=ref(0),tariffIds=ref([]),workingRecords=ref([]),includedSearch=ref(""),includedApi=ref(null),includedSelected=ref([]),errorMessage=ref("");const operationOptions=Object.freeze([{value:"increase",label:"Aumentar"},{value:"decrease",label:"Disminuir"}]),percentageMaximum=computed(()=>operation.value==="decrease"?100:1000),activeTariffs=computed(()=>props.tariffs.filter(x=>x.isActive!==false&&Number(x.position)>=1&&Number(x.position)<=6).sort((a,b)=>Number(a.position)-Number(b.position))),percentage=computed(()=>Number(percentageValue.value)||0),draftState=computed(()=>({operation:operation.value,percentage:percentage.value,tariffIds:[...tariffIds.value].map(Number).sort((a,b)=>a-b),examIds:workingRecords.value.map(x=>Number(x.id)).sort((a,b)=>a-b)})),signature=computed(()=>JSON.stringify(draftState.value)),hasChanges=computed(()=>Boolean(original.value)&&signature.value!==original.value),operationLabel=computed(()=>operation.value==="increase"?"Aumentar":"Disminuir"),percentageDisplay=computed(()=>percentage.value===null?"0":formatRegionalNumber(percentage.value,settings.settings,{maximumFractionDigits:4})),percentageError=computed(()=>percentage.value===null||percentage.value<=0?"Indica un porcentaje mayor que cero.":percentage.value>(operation.value==="decrease"?100:1000)?`El máximo es ${operation.value==="decrease"?100:1000}%.`:""),allSelected=computed(()=>activeTariffs.value.length>0&&activeTariffs.value.every(x=>tariffIds.value.includes(Number(x.id)))),groupCount=computed(()=>new Set(workingRecords.value.map(x=>x.group_id)).size),workingRows=computed(()=>workingRecords.value.map(x=>({...x,group_description:props.groups.find(g=>g.id===x.group_id)?.description||props.group?.description||""}))),previewRows=computed(()=>{if(percentageError.value||!tariffIds.value.length)return[];const factor=operation.value==="increase"?1+percentage.value/100:1-percentage.value/100;return workingRows.value.flatMap(exam=>activeTariffs.value.filter(t=>tariffIds.value.includes(Number(t.id))).map(t=>{const current=Number(exam[`cost${Number(t.position)}`])||0,result=Math.round((current*factor+Number.EPSILON)*100)/100;return{id:`${exam.id}-${t.id}`,group_description:exam.group_description,exam:exam.description,tariff:t.name,current,variation:Math.abs(result-current),result}}))}),components=Object.freeze({BioNexusGridActionsCell}),selection=Object.freeze({mode:"multiRow",checkboxes:true,headerCheckbox:true,selectAll:"filtered"}),includedColumns=computed(()=>[{field:"group_description",headerName:"Grupo",minWidth:230,flex:1},{field:"description",headerName:"Examen",minWidth:340,flex:1.7},{field:"abbreviation",headerName:"Abreviatura",minWidth:170,flex:.7},{colId:"actions",headerName:"Acciones",width:110,cellRenderer:"BioNexusGridActionsCell",cellRendererParams:{actions:[{key:"remove",label:"Quitar",icon:"delete",onClick:row=>remove(row.id)}]}}]),submitDisabled=computed(()=>props.saving||workingRecords.value.length===0||tariffIds.value.length===0||Boolean(percentageError.value));function getId({data}){return String(data.id)}function includedReady(event){includedApi.value=event.api;event.api.addEventListener("selectionChanged",()=>includedSelected.value=event.api.getSelectedRows()||[])}function addRecords(rows){const map=new Map(workingRecords.value.map(x=>[x.id,x]));for(const row of rows||[])map.set(row.id,row);workingRecords.value=[...map.values()].sort((a,b)=>a.group_id-b.group_id||a.description.localeCompare(b.description))}function remove(id){workingRecords.value=workingRecords.value.filter(x=>x.id!==id)}function removeSelected(){const ids=new Set(includedSelected.value.map(x=>x.id));workingRecords.value=workingRecords.value.filter(x=>!ids.has(x.id));includedApi.value?.deselectAll?.();includedSelected.value=[]}function clearAll(){workingRecords.value=[];includedSelected.value=[]}function toggleTariff(id,value){const number=Number(id);tariffIds.value=value?[...new Set([...tariffIds.value,number])]:tariffIds.value.filter(x=>x!==number)}function toggleAll(){tariffIds.value=allSelected.value?[]:activeTariffs.value.map(x=>Number(x.id))}function open(){showErrors.value=false;workingRecords.value=(props.selectedRecords||[]).map(record=>({...record}));includedSelected.value=[];operation.value="increase";percentageValue.value=0;tariffIds.value=activeTariffs.value.map(x=>Number(x.id));errorMessage.value="";original.value=signature.value;box.value?.open()}function submit(){showErrors.value=true;if(submitDisabled.value)return;emit("confirm",{examIds:workingRecords.value.map(x=>Number(x.id)),operation:operation.value,percentage:percentage.value,tariffIds:[...tariffIds.value]})}async function requestClose(){if(props.saving)return;if(hasChanges.value){const accepted=await discardDialog.value?.ask({kicker:"Confirmación",title:"Descartar cambios",message:"Hay cambios sin guardar. ¿Deseas salir y descartarlos?",icon:"warning",variant:"danger",confirmIcon:"delete",confirmText:"Sí, salir y descartar cambios",cancelText:"Continuar editando"});if(!accepted)return}closeDirect()}function closeDirect(){box.value?.close()}function markAppliedAndClose(){original.value=signature.value;closeDirect()}function close(){requestClose()}function reset(){includedSelected.value=[];errorMessage.value="";original.value=""}function setError(value){errorMessage.value=String(value||"")}function clearError(){errorMessage.value=""}defineExpose({open,close,requestClose,markAppliedAndClose,setError,clearError});</script>
<style scoped>.adjustment-operation{display:grid;gap:14px}.workspace{display:grid;gap:14px;width:100%;min-width:0;padding:14px}.workspace>section{width:100%;min-width:0}.summary{margin-top:var(--bio-nexus-space-3);padding:10px 12px;border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-info-soft);color:var(--bio-nexus-color-text-secondary)}.adjustment-top{display:grid;grid-template-columns:minmax(280px,420px) minmax(0,1fr);gap:16px;align-items:stretch}.controls{display:grid;grid-template-columns:1fr;gap:12px;align-content:start}.controls :deep(.bio-nexus-field){min-height:46px}.tariffs{display:grid;gap:10px;padding:12px 16px;border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md)}.tariffs header{display:flex;align-items:center;justify-content:space-between}.tariffs>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.summary{display:flex;justify-content:space-between}h3{margin:0 0 8px;color:var(--bio-nexus-color-primary-strong)}.workspace :deep(.bio-nexus-data-grid){width:100%;min-width:0}.preview-launch{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 18px;border:1px solid var(--bio-nexus-color-primary);border-left:5px solid var(--bio-nexus-color-accent);border-radius:var(--bio-nexus-radius-md);background:linear-gradient(135deg,var(--bio-nexus-color-info-soft),var(--bio-nexus-color-surface));box-shadow:0 7px 18px rgb(13 36 58 / 10%)}.preview-count{color:var(--bio-nexus-color-text-secondary);font-size:var(--bio-nexus-font-size-md);font-weight:var(--bio-nexus-font-weight-medium)}.preview-action{min-width:220px;box-shadow:0 5px 12px rgb(31 113 153 / 22%)}.preview-action:not(:disabled){animation:preview-attention 1.8s ease-out 1}@keyframes preview-attention{0%,100%{transform:none}45%{transform:translateY(-2px);box-shadow:0 8px 18px rgb(31 113 153 / 30%)}}@media(max-width:900px){.adjustment-top{grid-template-columns:1fr}.controls{grid-template-columns:1fr 1fr}}@media(max-width:720px){.adjustment-top,.controls,.tariffs>div{grid-template-columns:1fr}.summary{display:grid}}</style>
